#[derive(Clone, Debug, PartialEq)]
pub struct JsFunction {
    /// Stable identity: set once at creation, preserved through clone. Used by
    /// SameValue to detect "same function object" without Rc indirection.
    pub id: u64,
    pub name: Option<String>,
    pub params: Vec<Param>,
    pub body: FunctionBody,
    pub captured: Vec<StackFrame>,
    properties: HashMap<String, JsValue>,
    /// True for `async function` / async arrow functions.
    pub is_async: bool,
    /// True for `function*` — calling this function returns a GeneratorObject.
    pub is_generator: bool,
    /// True only for class constructors built by execute_class_decl.
    pub is_class_ctor: bool,
    /// True when the function body starts with a "use strict" directive.
    pub is_strict: bool,
    /// True for the synthesized `constructor(...args) { super(...args); }`.
    pub default_derived_ctor: bool,
    /// Superclass constructor for `super()` calls inside class constructors.
    pub super_ctor: Option<Box<JsValue>>,
    /// Instance field initializers run on `this` before the constructor body.
    pub instance_fields: Vec<ClassField>,
    /// Accessor properties installed directly on function objects, used by class statics.
    static_accessors: HashMap<String, Property>,
    /// Module URL active when the function was created. Used by deferred callbacks
    /// and async continuations for module-relative dynamic import() resolution.
    module_base_url: Option<String>,
}

fn next_fn_id() -> u64 {
    static CTR: AtomicU64 = AtomicU64::new(1);
    CTR.fetch_add(1, Ordering::Relaxed)
}

impl JsFunction {
    fn plain(
        name: Option<String>,
        params: Vec<Param>,
        body: FunctionBody,
        captured: Vec<StackFrame>,
    ) -> Self {
        let is_strict = Self::function_body_is_strict(&body);
        JsFunction {
            name,
            params,
            body,
            captured,
            properties: HashMap::new(),
            is_async: false,
            is_generator: false,
            is_class_ctor: false,
            is_strict,
            default_derived_ctor: false,
            super_ctor: None,
            instance_fields: Vec::new(),
            static_accessors: HashMap::new(),
            module_base_url: None,
            id: next_fn_id(),
        }
    }

    fn function_body_is_strict(body: &FunctionBody) -> bool {
        let FunctionBody::Block(block) = body else {
            return false;
        };
        for statement in &block.body {
            match statement {
                Statement::Expression(Expression::String(value)) if value == "use strict" => {
                    return true;
                }
                Statement::Expression(Expression::String(_)) => {}
                _ => break,
            }
        }
        false
    }
}

