#[derive(Default)]
pub struct ModuleExecutionCache {
    modules: HashMap<String, ModuleCacheEntry>,
}

enum ModuleCacheEntry {
    Loading(HashMap<String, JsValue>),
    Evaluated(HashMap<String, JsValue>),
}

impl ModuleCacheEntry {
    fn exports(&self) -> HashMap<String, JsValue> {
        match self {
            ModuleCacheEntry::Loading(exports) | ModuleCacheEntry::Evaluated(exports) => {
                exports.clone()
            }
        }
    }
}

// ─── Environment Record Slot (Phase B: const / let mutability) ───────────────

/// A single variable binding inside an environment record.
/// `mutable: false` → `const` binding; reassignment throws TypeError.
/// `initialized: false` → Temporal Dead Zone; access before the declaration throws ReferenceError.
#[derive(Clone, Debug)]
struct Slot {
    value: JsValue,
    mutable: bool,
    initialized: bool,
}

impl Slot {
    fn var(value: JsValue) -> Self {
        Slot {
            value,
            mutable: true,
            initialized: true,
        }
    }
    fn const_(value: JsValue) -> Self {
        Slot {
            value,
            mutable: false,
            initialized: true,
        }
    }
    /// Temporal Dead Zone placeholder — inserted at block entry for `let`/`const` bindings.
    fn tdz(mutable: bool) -> Self {
        Slot {
            value: JsValue::Undefined,
            mutable,
            initialized: false,
        }
    }
}

impl PartialEq for Slot {
    fn eq(&self, other: &Self) -> bool {
        self.value == other.value
            && self.mutable == other.mutable
            && self.initialized == other.initialized
    }
}

// ─── Environment Record Kind (ECMA-262 §9.1) ─────────────────────────────────

#[derive(Clone, Debug, PartialEq)]
enum EnvKind {
    /// Top-level script environment — `var` declarations live here.
    Global,
    /// Function body environment — `var` declarations land here.
    Function,
    /// Block `{ }` environment — `let`/`const` only, TDZ hoisting applies.
    Block,
}

// ─── Stack Frame ──────────────────────────────────────────────────────────────

#[derive(Clone, Debug)]
struct StackFrame {
    kind: EnvKind,
    locals: Rc<RefCell<HashMap<String, Slot>>>,
    module_base_url: Option<String>,
    strict: bool,
}

impl Default for StackFrame {
    fn default() -> Self {
        StackFrame {
            kind: EnvKind::Block,
            locals: Rc::new(RefCell::new(HashMap::new())),
            module_base_url: None,
            strict: false,
        }
    }
}

impl StackFrame {
    fn function_scope() -> Self {
        StackFrame {
            kind: EnvKind::Function,
            locals: Rc::new(RefCell::new(HashMap::new())),
            module_base_url: None,
            strict: false,
        }
    }
    fn global_scope() -> Self {
        StackFrame {
            kind: EnvKind::Global,
            locals: Rc::new(RefCell::new(HashMap::new())),
            module_base_url: None,
            strict: false,
        }
    }
    fn block_scope() -> Self {
        StackFrame {
            kind: EnvKind::Block,
            locals: Rc::new(RefCell::new(HashMap::new())),
            module_base_url: None,
            strict: false,
        }
    }
    /// True for environments where `var` declarations land (function and global).
    fn is_function_scope(&self) -> bool {
        matches!(self.kind, EnvKind::Function | EnvKind::Global)
    }
}

impl PartialEq for StackFrame {
    fn eq(&self, other: &Self) -> bool {
        Rc::ptr_eq(&self.locals, &other.locals)
    }
}

