    #[test]
    fn generator_labeled_break_after_yield_targets_outer_loop() {
        let program = crate::parse_script(
            r#"
            function* gen() {
                let out = "";
                outer: for (let i = 0; i < 3; i = i + 1) {
                    for (let j = 0; j < 3; j = j + 1) {
                        out = out + String(i) + ":" + String(j) + ",";
                        yield "pause";
                        break outer;
                    }
                }
                yield out;
            }
            let g = gen();
            let r1 = g.next();
            let r2 = g.next();
            document.getElementById("result").textContent =
                r1.value + "/" + r2.value + "/" + String(r2.done);
            "#,
        )
        .expect("script should parse");

        let mut state = BrowserExecutionState::default();
        state.execute_program(&program);

        assert_eq!(
            state.drain_effects(),
            vec![BrowserEffect::SetTextContent {
                element_id: "result".to_owned(),
                value: "pause/0:0,/false".to_owned(),
            }]
        );
    }

    #[test]
    fn async_labeled_break_after_await_targets_outer_loop() {
        let program = crate::parse_script(
            r#"
            let resolveLater;
            let p = new Promise(function (resolve) { resolveLater = resolve; });
            let out = "";

            async function run() {
                outer: for (let i = 0; i < 3; i = i + 1) {
                    for (let j = 0; j < 3; j = j + 1) {
                        out = out + String(i) + ":" + String(j) + ",";
                        await p;
                        break outer;
                    }
                }
                document.getElementById("result").textContent = out;
            }

            run();
            setTimeout(function () { resolveLater("resume"); }, 0);
            "#,
        )
        .expect("script should parse");

        let mut state = BrowserExecutionState::default();
        state.execute_program(&program);
        state.drain_effects();

        assert_eq!(
            state.poll_timers(0),
            vec![BrowserEffect::SetTextContent {
                element_id: "result".to_owned(),
                value: "0:0,".to_owned(),
            }]
        );
    }

    #[test]
    fn generator_labeled_continue_out_of_for_of_closes_iterator() {
        let program = crate::parse_script(
            r#"
            let output = "";
            let iterable = {};
            iterable[Symbol.iterator] = function () {
                let i = 0;
                return {
                    next: function () {
                        i = i + 1;
                        return { value: "A" + String(i), done: false };
                    },
                    return: function () {
                        output = output + "R";
                        return { done: true };
                    }
                };
            };
            function* gen() {
                outer: for (let i = 0; i < 1; i = i + 1) {
                    for (const value of iterable) {
                        output = output + value;
                        yield "pause";
                        continue outer;
                    }
                }
                yield output;
            }
            let g = gen();
            let r1 = g.next();
            let r2 = g.next();
            document.getElementById("result").textContent =
                r1.value + "/" + r2.value + "/" + String(r2.done);
            "#,
        )
        .expect("script should parse");

        let mut state = BrowserExecutionState::default();
        state.execute_program(&program);

        assert_eq!(
            state.drain_effects(),
            vec![BrowserEffect::SetTextContent {
                element_id: "result".to_owned(),
                value: "pause/A1R/false".to_owned(),
            }]
        );
    }

